def transform(grid):
    divider = next(i for i, row in enumerate(grid) if all(v == 5 for v in row))
    upper, lower = grid[:divider], grid[divider + 1:]

    colors = {v for row in grid for v in row if v not in (0, 5)}
    ratios = {}
    for color in colors:
        top_count = sum(v == color for row in upper for v in row)
        bottom_count = sum(v == color for row in lower for v in row)
        ratios[color] = bottom_count / top_count if top_count else float("inf")

    color = max(ratios, key=ratios.get)
    return [[color, color], [color, color]]
