def transform(grid):
    divider = next(i for i, row in enumerate(grid) if all(v == 5 for v in row))
    upper, lower = grid[:divider], grid[divider + 1:]
    colors = {v for row in grid for v in row if v not in (0, 5)}

    def counts(region, color):
        return sum(cell == color for row in region for cell in row)

    color = max(
        colors,
        key=lambda c: (counts(lower, c) / counts(upper, c), counts(lower, c))
    )
    return [[color, color], [color, color]]
